html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{% if letter_head and not no_letterhead %}
		<div class="letter-head">{{ letter_head }}</div>
	{% endif %}
	{% if print_heading_template %}
		{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
	{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break invoice-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>
	{%- if doc.meta.is_submittable and doc.docstatus==2-%}
		<div class="text-center" document-status="cancelled">
			<h4 style="margin-top: 20px;">{{ _("CANCELLED") }}</h4>
		</div>
	{%- endif -%}
	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}
		<div class="text-center" document-status="draft">
			<h4 style="margin-top: 20px !important;">{{ _("DRAFT") }}</h4>
		</div>
	{%- endif -%}

	<style>
		.letter-head {
			margin-top: 12px !important;
		}
		.invoice-wrapper {
			font-family: "Inter", sans-serif;
			color: var(--black-overlay-700);
		}

		.print-format-body {
			padding: 30px 12px 12px 12px !important;
		}

		body {
			margin-bottom: 0mm !important;
			padding: 0px !important;
		}

		table.info-table,
		table.items-table,
		table.tax-table {
			border-collapse: separate;
			border-spacing: 0;
			border: 1px solid #ededed;
			border-radius: 10px;
			overflow: hidden;
		}

		table.info-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px 10px !important;
		}
		table.items-table td,
		table.tax-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px;
		}

		table.info-table td:not(:first-of-type),
		table.items-table td:not(:first-of-type),
		table.tax-table td:not(:first-of-type) {
			border-left: 1px solid #ededed;
		}

		table.info-table tbody tr:last-of-type td,
		table.items-table tbody tr:last-of-type td,
		table.tax-table tbody tr:last-of-type td {
			border-bottom: none;
		}

		thead.table-header {
			background: #f8f8f8;
		}
		thead.table-header td {
			color: #7c7c7c;
		}

		.text-center {
			text-align: center;
		}
		.text-left {
			text-align: left;
		}
		.text-right {
			text-align: right;
		}
		.text-muted {
			color: #7c7c7c;
		}
		.text-dark {
			color: #525252;
		}
		.text-bold {
			font-weight: bold;
		}
		.small-text {
			color: #666;
		}

		.mt-10 {
			margin-top: 10px;
		}
		.mt-15 {
			margin-top: 15px;
		}
		.mt-20 {
			margin-top: 20px;
		}
		.mt-40 {
			margin-top: 40px;
		}
		.mt-80 {
			margin-top: 80px;
		}
		.mb-20 {
			margin-bottom: 20px;
		}
		.pb-8 {
			padding-bottom: 8px;
		}
		.amount-width {
			width: 110px;
		}

		.totals-table {
			border-radius: 5px;
			width: 100%;
		}
		.totals-table td {
			padding: 4px 8px;
		}
		.totals-table tr {
			border-bottom: 1px solid #ededed;
			position: relative;
		}
		.totals-table tr td {
			position: relative;
		}
		.totals-table tr td div {
			width: 12%;
			height: 14px;
			background-color: white;
			position: absolute;
			bottom: -6px;
			left: 0%;
			color: white;
		}
		.totals-table tr:last-child {
			border-bottom: none;
		}
		.totals-table .grand-total td {
			padding: 6px 8px;
			font-weight: bold;
		}

		.words-box {
			background: #f8f8f8;
			border-radius: 8px;
			padding: 8px;
			line-height: 21px;
			letter-spacing: 0.21px;
			font-size: small;
		}

		.info-card {
			color: #7c7c7c;
		}

		.title {
			color: #7c7c7c !important;
		}

		.heading {
			color: #525252 !important;
			font-weight: 300;
		}

		.print-format {
			color: #171717;
			font-size: 14px;
			font-style: normal;
			font-weight: 420;
			line-height: 21px;
			padding: 0px;
			letter-spacing: 0.14px;
			margin-left: 0mm !important;
			margin-right: 0mm !important;
		}
		.letter-head-footer {
			margin-top: 0px !important;
		}
		.print-heading {
			margin-top: 0px !important;
			margin-bottom: 0px !important;
			padding-bottom: 0px !important;
		}
	</style>
	<div class="print-format-body">
		<table class="info-table mb-20" style="width: 100%">
			<tr>
				<td style="width: 50%">
					<span class="heading">{{ _("Customer Name") }}:</span> {{doc.customer_name }}
				</td>
				<td style="width: 50%">
					<span class="heading">{{ _("Payment Due Date") }}:</span> {{
					frappe.utils.format_date(doc.due_date) }}
				</td>
			</tr>
			<tr>
				<td><span class="heading">{{ _("Invoice Number") }}:</span> {{ doc.name }}</td>
				<td>
					<span class="heading">{{ _("Invoice Date") }}:</span> {{
					frappe.utils.format_date(doc.posting_date) }}
				</td>
			</tr>
			<tr>
				<td><span class="heading">{{ _("Bill From") }}:</span><br />
					{% if doc.company_address %}
                        {% set company_address = frappe.db.get_value("Address", doc.company_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
                        {{  doc.company }}<br>
                        {{ company_address.get("address_line1") or "" }}<br>
                        {% if company_address.get("address_line2") %}{{ company_address.get("address_line2") }}<br>{% endif %}
                        {{ company_address.get("city") or "" }}, {{ company_address.get("state") or "" }} {{ company_address.get("pincode") or "" }}, {{ company_address.get("country") or "" }}<br>
                    {% endif %}
                    {% set company_gstin = frappe.db.get_value("Company", doc.company, "gstin") %}
                    {% if company_gstin %}
                        <span class="heading">GSTIN:</span> {{ company_gstin }}<br>
                     {% endif %}
				</td>

				<td>
                    <span class="heading">{{ _("Bill To") }}:</span><br />

                    {% if doc.customer_address %}
                        {% set customer_address = frappe.db.get_value(
                            "Address",
                            doc.customer_address,
                            [
                                "address_line1",
                                "address_line2",
                                "city",
                                "state",
                                "pincode",
                                "country",
                                "gstin"
                            ],
                            as_dict=True
                        ) %}
                    {% endif %}

                    {% set customer = frappe.db.get_value(
                        "Customer",
                        doc.customer,
                        ["custom_drug_licence_number"],
                        as_dict=True
                    ) %}

                    {{ doc.customer_name }}<br>

                    {{ customer_address.address_line1 or "" }}<br>

                    {% if customer_address.address_line2 %}
                        {{ customer_address.address_line2 }}<br>
                    {% endif %}

                    {{ customer_address.city or "" }}
                    {{ customer_address.state or "" }}
                    {{ customer_address.pincode or "" }}
                    {{ customer_address.country or "" }}<br>

                    {% if customer.custom_drug_licence_number %}
                        <span class="heading">DL No:</span>
                        {{ customer.custom_drug_licence_number }}<br>
                    {% endif %}

                    {% if customer_address.gstin %}
                        <span class="heading">GSTIN:</span>
                        {{ customer_address.gstin }}<br>
                    {% endif %}
                </td>

			</tr>
		</table>

		<!-- Items Table -->
        {% set item_naming_by = frappe.db.get_single_value("Stock Settings", "item_naming_by") %}
        <table class="items-table mt-15" style="width: 100%">
             <thead class="table-header">
                  <tr>
                    <td class="text-center">{{ _("No") }}</td>
                    <td class="text-left">{{ _("Item") }}</td>
                    {% if item_naming_by != "Item Code" %}
                        <td class="text-left">{{ _("Item Code") }}</td>
                    {% endif %}
                    <td class="text-center">{{ _("HSN") }}</td>
                    <td class="text-center">{{ _("Batch No") }}</td>
                    <td class="text-center">{{ _("Expiry") }}</td>
                    <td class="text-right">{{ _("Quantity") }}</td>
                    <td class="text-right">{{ _("Rate") }}</td>
                    <td class="text-right">{{ _("Amount") }}</td>
                </tr>
            </thead>
            <tbody>
               {% for item in doc.items %}
                    <tr>
                        <td class="text-center text-dark">{{ loop.index }}</td>
                        <td>{{ item.item_name }}</td>
                        {% if item_naming_by != "Item Code" %}
                            <td class="text-left">{{ item.item_code }}</td>
                        {% endif %}
                        <td class="text-center text-dark">{{ item.gst_hsn_code or "" }}</td>
                        <td class="text-center text-dark">{{ item.batch_no or "" }}</td>
                        <td class="text-center text-dark">
                            {%- if item.batch_no -%}
                                {%- set expiry = frappe.db.get_value("Batch", item.batch_no, "expiry_date") -%}
                                {%- if expiry -%}{{ frappe.utils.format_date(expiry,"MM-YYYY") }}{%- endif -%}
                            {%- endif -%}
                        </td>
                        <td class="text-right text-dark">{{ item.get_formatted("qty", 0) | int}} {{ item.uom}}</td>
                        <td class="text-right text-dark">{{ item.get_formatted("net_rate", doc) }}</td>
                        <td class="text-right" style="color: #171717">
                            {{ item.get_formatted("net_amount", doc) }}
                        </td>
                    </tr>
                 {% endfor %}
            </tbody>
        </table>

		<!-- Totals Section -->
		<table style="width:100%; margin-top: 15px">
			<td style="vertical-align: bottom !important; width: 60%;">
				<p class="title">{{ _("Total in words") }}</p>
				<div class="words-box text-uppercase">{{ doc.in_words }}</div>
			</td>
			<td>
				&nbsp;
			</td>
			<td style="width: 38%;">
				<table class="totals-table">
					<tr>
						<td class="text-right text-muted"><div></div>{{ _("Sub Total:") }}</td>
						<td class="text-right amount-width">{{ doc.get_formatted("total", doc) }}</td>
					</tr>
					{%- if doc.apply_discount_on == "Net Total" -%}
						<tr>
							<td class="text-right text-muted">
								<div></div>{{ _("Discount") }} ({{ doc.additional_discount_percentage }}%):
							</td>
							<td class="text-right amount-width">{{ doc.get_formatted("discount_amount", doc) }}</td>
						</tr>
					{%- endif -%}
					{%- for tax in doc.taxes -%}
						{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}
							<tr>
								<td class="text-right text-muted"><div></div>{{ tax.get_formatted("description") }} ({{ tax.get_formatted("rate") }}%):</td>
								<td class="text-right amount-width">{{ tax.get_formatted("tax_amount") }}</td>
							</tr>
						{%- endif -%}
					{%- endfor -%}
					{%- if doc.apply_discount_on == "Grand Total" -%}
						<tr>
							<td class="text-right text-muted">
								<div></div>{{ _("Discount") }} ({{ doc.additional_discount_percentage }}%):
							</td>
							<td class="text-right amount-width">{{ doc.get_formatted("discount_amount", doc) }}</td>
						</tr>
					{%- endif -%}
					<tr class="grand-total">
						<td class="text-right">{{ _("Grand Total:") }}</td>
						<td class="text-right amount-width">{{ doc.get_formatted("grand_total", doc) }}</td>
					</tr>
				</table>
			</td>
		</table>

		<!-- Terms + QR -->
        <table style="width:100%; margin-top:40px;">
             <tr>
                <!-- Terms -->
                <td style="width:75%; vertical-align:top;">
                    {% if doc.terms %}
                    <div class="info-card">
                        <div style="font-weight:bold; margin-bottom:6px;">
                            {{ _("Terms and Conditions") }}
                        </div>
                        {{ doc.terms }}
                    </div>
                    {% endif %}
                </td>

                <!-- QR Code -->
                <td style="width:15%; text-align:center; vertical-align:top;">
                {% set upi_url = doc.custom_upi_qr or
                ("upi://pay?pa=exponit@upi&pn=" ~
                (doc.company | urlencode) ~
                "&am=" ~ doc.grand_total ~
                "&cu=INR&tn=Invoice%20" ~ doc.name) %}
                {% set qr_image_data = get_upi_qr_data_url(upi_url) %}
                <div style="font-weight:semi-bold;font-siz:10px; margin-bottom:8px;">
                    Scan to Pay
                </div>
                {% if qr_image_data %}
                    <img src="{{ qr_image_data }}"
                         alt="UPI QR"
                         >
                {% endif %}
                </td>
            </tr>   
        </table>
</div>
{% endfor %}

{% set items = get_pharma_invoice_items(doc) %}
{% set totals = get_pharma_totals(doc, items) %}
{% set gst = get_pharma_gst_summary(doc, items) %}
{% set comp = get_company_pharma_info(doc) %}
{% set cust = get_customer_pharma_info(doc) %}
{% set bank = get_pharma_bank_details(doc) %}
{% set barcode_url = get_barcode_svg_data_url(doc.name) %}
{% set upi_url = doc.custom_upi_qr or ("upi://pay?pa=exponit@upi&pn=" ~ (doc.company | urlencode) ~ "&am=" ~ doc.grand_total ~ "&cu=INR&tn=Invoice%20" ~ doc.name) %}
{% set qr_image_data = get_upi_qr_data_url(upi_url) %}

<style>
  @page {
    size: A4 portrait;
    margin: 4mm 5mm;
  }

  * {
    box-sizing: border-box;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  body {
    margin: 0;
    padding: 0;
    background: #fff;
  }

  .pharma-invoice-container {
    font-family: Arial, Helvetica, sans-serif;
    color: #000;
    font-size: 7pt;
    line-height: 1.2;
    background: #fff;
    width: 100%;
    margin: 0;
    padding: 0;
    page-break-inside: avoid;
  }

  /* Top Meta Bar */
  .top-meta-bar {
    display: table;
    width: 100%;
    font-size: 7.2pt;
    font-weight: bold;
    padding-bottom: 2px;
    margin-bottom: 2px;
  }
  .top-meta-left { display: table-cell; width: 33.3%; text-align: left; }
  .top-meta-center { display: table-cell; width: 33.3%; text-align: center; }
  .top-meta-right { display: table-cell; width: 33.3%; text-align: right; }

  /* Header Box */
  .header-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    table-layout: fixed;
    margin-bottom: 0px;
  }

  .header-table > tbody > tr > td {
    border: 1px solid #000;
    padding: 3px 4px;
    vertical-align: top;
  }

  .company-title {
    font-size: 10pt;
    font-weight: 900;
    letter-spacing: 0.3px;
    color: #000;
    margin-bottom: 2px;
  }

  .customer-title {
    font-size: 9.5pt;
    font-weight: 900;
    color: #000;
    margin-bottom: 1px;
  }

  .header-label {
    font-weight: bold;
    color: #000;
  }

  .barcode-img {
    height: 20px;
    max-width: 110px;
    display: inline-block;
  }

  /* Items Table */
  .items-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    border-top: none;
    table-layout: fixed;
    margin-bottom: 0px;
  }

  .items-table th {
    background-color: #f0f0f0;
    color: #000;
    font-weight: bold;
    font-size: 5.8pt;
    letter-spacing: -0.1px;
    text-transform: uppercase;
    border: 1px solid #000;
    padding: 2px 1px;
    text-align: center;
    vertical-align: middle;
    line-height: 1.1;
    overflow: hidden;
  }

  .items-table td {
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-top: 1px solid #eee;
    border-bottom: 1px solid #eee;
    padding: 2px 1px;
    font-size: 6.8pt;
    vertical-align: middle;
    white-space: nowrap;
    overflow: visible;
  }

  .items-table td.product-col {
    white-space: normal;
    font-size: 7.2pt;
    word-break: break-word;
    overflow: visible;
    line-height: 1.15;
  }

  .items-table tbody tr.empty-row td {
    border-top: none;
    border-bottom: none;
    height: 16px;
  }

  .items-table tbody tr:last-child td {
    border-bottom: 1px solid #000;
  }

  /* Utilities */
  .text-center { text-align: center !important; }
  .text-left { text-align: left !important; }
  .text-right { text-align: right !important; }
  .font-bold { font-weight: bold !important; }

  .scheme-val {
    font-weight: 900;
    color: #0b4594;
    font-size: 7.5pt;
  }

  /* Banners */
  .alert-banner {
    width: 100%;
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    padding: 1.5px 4px;
    font-size: 6.8pt;
    font-weight: bold;
    background-color: #fff;
    box-sizing: border-box;
  }

  .complaints-banner {
    border-top: 1px solid #000;
    border-bottom: 1px solid #bbb;
    text-align: center;
  }

  .message-banner {
    border-bottom: 1px solid #000;
    background-color: #fafafa;
    display: table;
    width: 100%;
  }

  .msg-label {
    display: table-cell;
    width: 55px;
    font-weight: 900;
    border-right: 1px solid #000;
    padding-right: 4px;
  }

  .msg-content {
    display: table-cell;
    padding-left: 6px;
    font-weight: bold;
    letter-spacing: 0.3px;
  }

  /* Footer Table */
  .footer-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    border-top: none;
    table-layout: fixed;
  }

  .footer-table > tbody > tr > td {
    border: 1px solid #000;
    padding: 2.5px 3.5px;
    vertical-align: top;
  }

  /* GST Slab Table */
  .gst-slab-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 6.2pt;
    table-layout: fixed;
  }

  .gst-slab-table th, .gst-slab-table td {
    border: 1px solid #888;
    padding: 1px 1px;
    text-align: right;
    white-space: nowrap;
    overflow: hidden;
  }

  .gst-slab-table th {
    background-color: #f0f0f0;
    font-weight: bold;
    text-align: center;
    line-height: 1.1;
  }

  .gst-slab-table tr.total-row td {
    border-top: 1px solid #000;
    font-weight: bold;
    background-color: #f0f0f0;
  }

  /* Totals Grid */
  .totals-grid {
    width: 100%;
    border-collapse: collapse;
    font-size: 7.2pt;
    table-layout: fixed;
  }

  .totals-grid td {
    border: none;
    padding: 1px 1px;
    white-space: nowrap;
  }

  .to-pay-row {
    border-top: 1px solid #000 !important;
    border-bottom: 1px solid #000 !important;
    font-size: 9.5pt !important;
    font-weight: 900 !important;
  }

  .signatory-box {
    text-align: center;
  }

  .signatory-space {
    height: 25px;
  }

  .qr-box {
    text-align: center;
  }

  .qr-box img {
    width: 52px;
    height: 52px;
    border: 1px solid #555;
    padding: 1px;
    background: #fff;
  }
</style>

<div class="pharma-invoice-container">

  <!-- Top bar -->
  <div class="top-meta-bar">
    <div class="top-meta-left">E2,C2,C4,D1,D3,F3,G2</div>
    <div class="top-meta-center">Copy No: 01</div>
    <div class="top-meta-right">{% if doc.custom_invoice_copy %}{{ doc.custom_invoice_copy | upper }}{% else %}CUSTOMER COPY{% endif %}</div>
  </div>

  <!-- Header Table -->
  <table class="header-table">
    <tr>
      <!-- Left Box: Distributor Details -->
      <td style="width: 50%;">
        <div class="company-title">{{ comp.name }}</div>
        <div style="font-size: 7.2pt; line-height: 1.25;">
          {{ comp.address_line1 }}{% if comp.address_line2 %}, {{ comp.address_line2 }}{% endif %}<br>
          {{ comp.city }} - {{ comp.pincode }}<br>
          <span class="header-label">Ph.No. &nbsp; &nbsp; &nbsp; &nbsp; :</span> {{ comp.phone }}<br>
          <span class="header-label">CIN &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :</span> {{ comp.cin }}<br>
          <span class="header-label">GSTIN. &nbsp; &nbsp; &nbsp; :</span> {{ comp.gstin }} &nbsp; &nbsp; <span class="header-label">STATE :</span> {{ comp.state_code }}<br>
          <span class="header-label">DL NO. &nbsp; &nbsp; &nbsp; :</span> {{ comp.dl_no }}<br>
          <span class="header-label">Food Lic. &nbsp; :</span> {{ comp.food_lic }} &nbsp; &nbsp; <span class="header-label">PAN:</span> {{ comp.pan }}<br>
          <span class="header-label">Mail id &nbsp; &nbsp; &nbsp; :</span> {{ comp.email }}
        </div>
      </td>

      <!-- Right Box: Invoice & Customer Details -->
      <td style="width: 50%;">
        <table style="width: 100%; border: none; border-collapse: collapse;">
          <tr>
            <td style="border: none; padding: 0; vertical-align: top;">
              <span style="font-size: 8.8pt; font-weight: 900;">GST INVOICE : {{ doc.name }}</span><br>
              <span class="header-label">Inv. Date :</span> {{ cust.inv_date }}<br>
              <span class="header-label">Party Code:</span> {{ cust.party_code }}
            </td>
            <td style="border: none; padding: 0; text-align: right; vertical-align: top;">
              {% if barcode_url %}
                <img src="{{ barcode_url }}" class="barcode-img" alt="Barcode"><br>
                <span style="font-size: 6.2pt; letter-spacing: 0.5px; font-family: monospace;">*{{ doc.name }}*</span>
              {% endif %}
            </td>
          </tr>
        </table>

        <!-- Customer Name & Address -->
        <div style="margin-top: 2px;">
          <div class="customer-title">{{ cust.customer_name }} $</div>
          <div style="font-size: 7.2pt; line-height: 1.2;">
            {{ cust.address_line1 }}{% if cust.address_line2 %}, {{ cust.address_line2 }}{% endif %}
            {% if cust.city %}, {{ cust.city }}{% endif %}{% if cust.pincode %} - {{ cust.pincode }}{% endif %}
          </div>
        </div>

        <!-- Metadata Grid -->
        <table style="width: 100%; border: none; border-collapse: collapse; font-size: 7pt; margin-top: 2px;">
          <tr>
            <td style="border: none; padding: 0.5px 0;"><span class="header-label">Visit Day :</span> {{ cust.visit_day }}</td>
            <td style="border: none; padding: 0.5px 0;"><span class="header-label">S Code :</span> {{ cust.s_code }}</td>
            <td style="border: none; padding: 0.5px 0;" class="text-right"><span class="header-label">{{ cust.route }}</span></td>
          </tr>
          <tr>
            <td style="border: none; padding: 0.5px 0;"><span class="header-label">Due Date :</span> {{ cust.due_date }}</td>
            <td style="border: none; padding: 0.5px 0;" colspan="2"><span class="header-label">Mobile :</span> {{ cust.mobile }}</td>
          </tr>
          <tr>
            <td style="border: none; padding: 0.5px 0;"><span class="header-label">Ph.:</span> {{ cust.phone }}</td>
            <td style="border: none; padding: 0.5px 0;" colspan="2"><span class="header-label">Area :</span> {{ cust.area }}</td>
          </tr>
          <tr>
            <td style="border: none; padding: 0.5px 0;" colspan="2"><span class="header-label">D.L. No. :</span> {{ cust.dl_no }}</td>
            <td style="border: none; padding: 0.5px 0;" class="text-right"><span class="header-label">FOOD LIC. :</span> {{ cust.food_lic }}</td>
          </tr>
          <tr>
            <td style="border: none; padding: 0.5px 0;" colspan="3">
              <span class="header-label">GSTIN:</span> {{ cust.gstin }} &nbsp;
              <span class="header-label">State :</span> {{ cust.state_full }} &nbsp;
              <span class="header-label">PAN :</span> {{ cust.pan }} &nbsp;
              <span class="header-label">NDPS - II :</span> {{ cust.ndps }}
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <!-- Items Table (16 Columns) -->
  <table class="items-table">
    <thead>
      <tr>
        <th style="width: 4.5%;">LOC/<br>ROW</th>
        <th style="width: 4.5%;">MFR/<br>BY</th>
        <th style="width: 17.5%; text-align: left; padding-left: 3px;">PRODUCT</th>
        <th style="width: 4.5%;">PACK</th>
        <th style="width: 4%;">QTY</th>
        <th style="width: 6.5%;">SCH%<br>/QTY</th>
        <th style="width: 9.5%;">BATCH</th>
        <th style="width: 5.5%;">EXP.<br>DATE</th>
        <th style="width: 6%;">MRP</th>
        <th style="width: 6%;">SALE<br>RATE</th>
        <th style="width: 7%;">PROD.<br>VALUE</th>
        <th style="width: 4%;">DIS<br>%</th>
        <th style="width: 7.5%;">HSN<br>CODE</th>
        <th style="width: 4%;">GST<br>%</th>
        <th style="width: 5.5%;">GST<br>VAL</th>
        <th style="width: 7.5%;">NET<br>VALUE</th>
      </tr>
    </thead>
    <tbody>
      {% for item in items %}
      <tr>
        <td class="text-center">{{ item.loc_row }}</td>
        <td class="text-center font-bold">{{ item.mfac_by }}</td>
        <td class="text-left font-bold product-col" style="padding-left: 3px;">{{ item.product }}</td>
        <td class="text-center">{{ item.pack }}</td>
        <td class="text-right font-bold">{{ item.billed_qty }}</td>
        <td class="text-center scheme-val">{{ item.scheme }}</td>
        <td class="text-center">{{ item.batch }}</td>
        <td class="text-center">{{ item.exp_date }}</td>
        <td class="text-right font-bold">{{ item.mrp }}</td>
        <td class="text-right">{{ item.sale_rate }}</td>
        <td class="text-right">{{ item.product_value }}</td>
        <td class="text-right">{{ item.disc_percent }}</td>
        <td class="text-center">{{ item.hsn_code }}</td>
        <td class="text-center">{{ item.gst_rate }}</td>
        <td class="text-right">{{ item.gst_value }}</td>
        <td class="text-right font-bold">{{ item.net_value }}</td>
      </tr>
      {% endfor %}

      {# Filler blank rows if fewer than 7 items to keep invoice structure consistent #}
      {% set remaining_rows = 7 - (items | length) %}
      {% if remaining_rows > 0 %}
        {% for _ in range(remaining_rows) %}
        <tr class="empty-row">
          <td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td>
          <td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td>
        </tr>
        {% endfor %}
      {% endif %}
    </tbody>
  </table>

  <!-- Banners -->
  <div class="alert-banner complaints-banner">
    FOR ANY COMPLAINTS PLS INFORM {{ comp.phone }} IN 24 HRS. &amp; PLS COLLECT ORIGINAL BILL WHEN YOU MAKE PAYMENT
  </div>
  <div class="alert-banner message-banner">
    <div class="msg-label">Message</div>
    <div class="msg-content">*** {{ comp.name | upper }} - ALL PRODUCTS AVAILABLE ***</div>
  </div>

  <!-- Footer Table -->
  <table class="footer-table">
    <tr>
      <!-- Sub-block 1: Left (Items, Bank Details, Times) -->
      <td style="width: 30%;">
        <div style="font-size: 7.2pt; line-height: 1.3;">
          <span class="header-label">Total Items :</span> &nbsp; <span class="font-bold">{{ totals.total_items }}</span><br>
          <span class="header-label">Total Qty &nbsp; &nbsp;:</span> &nbsp; <span class="font-bold">{{ totals.total_qty }}</span>
          {% if totals.total_free_qty > 0 %}
            <span style="font-size: 6.8pt; color: #333;">({{ totals.total_billed_qty }} + {{ totals.total_free_qty }} Free)</span>
          {% endif %}
          <div style="margin-top: 4px; font-size: 6.8pt; border-top: 1px dotted #888; padding-top: 2px;">
            <span class="header-label">OUR BANK DETAILS:</span><br>
            {{ bank.bank_name }}, {{ bank.branch }}<br>
            <span class="header-label">A/C NO.</span> {{ bank.account_no }}<br>
            <span class="header-label">IFSC CODE:</span> {{ bank.ifsc_code }}
          </div>
          <div style="margin-top: 5px; font-size: 6.5pt; color: #444;">
            Print Time : {{ frappe.utils.now_datetime().strftime('%I:%M%p') }} &nbsp;
            Chkd By : ______<br>
            Prep By : {{ (doc.owner or 'ADMIN').split('@')[0] | upper }}
          </div>
        </div>
      </td>

      <!-- Sub-block 2: Center (GST Slab Breakdown) -->
      <td style="width: 42%;">
        <table class="gst-slab-table">
          <thead>
            <tr>
              <th style="width: 12%;">GST%</th>
              <th style="width: 24%;">Taxable<br>Amt.</th>
              {% if gst.is_inter_state %}
                <th style="width: 28%;">IGST<br>%</th>
                <th style="width: 36%;">IGST<br>Amt</th>
              {% else %}
                <th style="width: 16%;">SGST<br>%</th>
                <th style="width: 16%;">SGST<br>Amt</th>
                <th style="width: 16%;">CGST<br>%</th>
                <th style="width: 16%;">CGST<br>Amt</th>
              {% endif %}
            </tr>
          </thead>
          <tbody>
            {% for slab in gst.slabs %}
            <tr>
              <td class="text-center font-bold">{{ slab.rate_label }}</td>
              <td>{{ "%.2f"|format(slab.taxable) }}</td>
              {% if gst.is_inter_state %}
                <td class="text-center">{{ "%.1f"|format(slab.igst_rate) }}%</td>
                <td>{{ "%.2f"|format(slab.igst_amt) }}</td>
              {% else %}
                <td class="text-center">{{ "%.1f"|format(slab.sgst_rate) }}%</td>
                <td>{{ "%.2f"|format(slab.sgst_amt) }}</td>
                <td class="text-center">{{ "%.1f"|format(slab.cgst_rate) }}%</td>
                <td>{{ "%.2f"|format(slab.cgst_amt) }}</td>
              {% endif %}
            </tr>
            {% endfor %}
            <tr class="total-row">
              <td class="text-center">Total</td>
              <td>{{ gst.total_taxable }}</td>
              {% if gst.is_inter_state %}
                <td></td>
                <td>{{ gst.total_igst }}</td>
              {% else %}
                <td></td>
                <td>{{ gst.total_sgst }}</td>
                <td></td>
                <td>{{ gst.total_cgst }}</td>
              {% endif %}
            </tr>
          </tbody>
        </table>

        <!-- Ack & E-Waybill info -->
        <div style="margin-top: 4px; font-size: 6.5pt; color: #444;">
          ACK NO. : {% if doc.irn %}{{ doc.irn[:20] }}...{% endif %}<br>
          ACK DT : {{ cust.inv_date }} &nbsp; &nbsp; &nbsp;
          EWB NO. : {{ doc.ewaybill or '' }}
        </div>
      </td>

      <!-- Sub-block 3: Right (Totals, UPI QR, Signatory) -->
      <td style="width: 28%;">
        <table class="totals-grid">
          <tr>
            <td style="width: 52%;" class="header-label">Gross :</td>
            <td style="width: 48%;" class="text-right font-bold">{{ totals.gross }}</td>
          </tr>
          <tr>
            <td class="header-label">Sch. Disc :</td>
            <td class="text-right">{{ totals.sch_disc }}</td>
          </tr>
          <tr>
            <td class="header-label">Disc Amt :</td>
            <td class="text-right">{{ totals.disc_amt }}</td>
          </tr>
          <tr>
            <td class="header-label">Tax Amt :</td>
            <td class="text-right">{{ totals.tax_amt }}</td>
          </tr>
          <tr>
            <td class="header-label">TCS % 0.000 :</td>
            <td class="text-right">{{ totals.tcs_amt }}</td>
          </tr>
          <tr style="border-top: 1px solid #aaa;">
            <td class="header-label font-bold">Grand Total :</td>
            <td class="text-right font-bold">{{ totals.grand_total }}</td>
          </tr>
          <tr>
            <td class="header-label">Cr No. :</td>
            <td class="text-right">{{ totals.cr_no }}</td>
          </tr>
          <tr>
            <td class="header-label">Db No. :</td>
            <td class="text-right">{{ totals.db_no }}</td>
          </tr>
          <tr class="to-pay-row">
            <td style="padding: 2px 0;">To Pay :</td>
            <td class="text-right" style="padding: 2px 0; font-size: 10pt; font-weight: 900;">{{ totals.to_pay }}</td>
          </tr>
        </table>

        <!-- Signatory & UPI QR -->
        <table style="width: 100%; border: none; border-collapse: collapse; margin-top: 3px;">
          <tr>
            {% if qr_image_data %}
            <td style="width: 42%; border: none; padding: 0; vertical-align: middle; text-align: center;">
              <div class="qr-box">
                <img src="{{ qr_image_data }}" alt="UPI QR">
                <div style="font-size: 6pt; font-weight: bold; color: #333;">Scan to Pay</div>
              </div>
            </td>
            {% endif %}
            <td style="border: none; padding: 0; vertical-align: bottom; text-align: center;">
              <div class="signatory-box">
                <div style="font-size: 7pt; font-weight: bold;">For {{ comp.name }}</div>
                <div class="signatory-space"></div>
                <div style="font-size: 7pt; font-weight: bold; border-top: 1px solid #555; display: inline-block; padding-top: 1px;">
                  Authorised Signatory
                </div>
              </div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

</div>
